GPU_MEM_SIZE = 80  # GB


# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Use a greedy incumbent, then binary-search a globally coupled MILP KVPR bound."""
    eps = 1e-8
    if gpu_num <= 0:
        raise ValueError("gpu_num must be positive")
    n = len(models)
    loads = [float(m.req_rate / m.slo) for m in models]
    sizes = [float(m.model_size) for m in models]
    if any(s >= GPU_MEM_SIZE - eps for s in sizes):
        raise ValueError("A model leaves no positive KV-cache memory on a GPU")

    order = sorted(range(n), key=lambda i: (-loads[i], -sizes[i], i))
    bins = [[] for _ in range(gpu_num)]
    rem = [float(GPU_MEM_SIZE)] * gpu_num
    load_sum = [0.0] * gpu_num
    for i in order:
        choices = [(load_sum[g] / rem[g], -rem[g], g)
                   for g in range(gpu_num) if rem[g] - sizes[i] > eps]
        if not choices:
            raise ValueError("Unable to find a feasible positive-residual-memory placement")
        g = min(choices)[2]
        bins[g].append(i)
        rem[g] -= sizes[i]
        load_sum[g] += loads[i]

    def pressure(bs):
        return max(load_sum[g] / rem[g] for g in range(gpu_num))

    incumbent = [x[:] for x in bins]
    upper = pressure(incumbent)
    lower = max(
        [loads[i] / (GPU_MEM_SIZE - sizes[i]) for i in range(n)] +
        [sum(loads) / (gpu_num * GPU_MEM_SIZE - sum(sizes)), 0.0]
    )

    try:
        import numpy as np
        from scipy.optimize import milp, Bounds, LinearConstraint
        from scipy.sparse import lil_matrix

        v = n * gpu_num
        A = lil_matrix((n + 2 * gpu_num, v), dtype=float)
        for i in range(n):
            for g in range(gpu_num):
                A[i, i * gpu_num + g] = 1.0
        for g in range(gpu_num):
            for i in range(n):
                k = i * gpu_num + g
                A[n + g, k] = sizes[i]
                A[n + gpu_num + g, k] = loads[i]
        best = incumbent
        lo, hi = lower, upper
        for _ in range(24):
            mid = (lo + hi) / 2.0
            for g in range(gpu_num):
                for i in range(n):
                    A[n + gpu_num + g, i * gpu_num + g] = loads[i] + mid * sizes[i]
            lb = np.r_[np.ones(n), np.full(gpu_num, -np.inf),
                       np.full(gpu_num, -np.inf)]
            ub = np.r_[np.ones(n), np.full(gpu_num, GPU_MEM_SIZE - eps),
                       np.full(gpu_num, GPU_MEM_SIZE * mid)]
            result = milp(np.zeros(v), integrality=np.ones(v),
                          bounds=Bounds(0, 1),
                          constraints=LinearConstraint(A.tocsr(), lb, ub),
                          options={"time_limit": 0.15})
            if not result.success or result.x is None:
                lo = mid
                continue
            trial = [[] for _ in range(gpu_num)]
            for i in range(n):
                g = int(np.argmax(result.x[i * gpu_num:(i + 1) * gpu_num]))
                trial[g].append(i)
            tr = [GPU_MEM_SIZE - sum(sizes[i] for i in trial[g])
                  for g in range(gpu_num)]
            tl = [sum(loads[i] for i in trial[g]) for g in range(gpu_num)]
            if min(tr) > eps and max(tl[g] / tr[g] for g in range(gpu_num)) <= mid + 1e-7:
                best, hi = trial, mid
            else:
                lo = mid
        bins = best
    except Exception:
        pass

    # Evacuate selected subsets of the bottleneck GPU to all other GPUs.
    def gpu_pressure(items):
        free = GPU_MEM_SIZE - sum(sizes[i] for i in items)
        return (sum(loads[i] for i in items) / free
                if free > eps else float("inf"))

    def placement_pressure(state):
        return max(gpu_pressure(group) for group in state)

    try:
        import numpy as np
        from scipy.optimize import milp, Bounds, LinearConstraint
        from scipy.sparse import lil_matrix

        for _ in range(6):
            worst = max(range(gpu_num), key=lambda g: gpu_pressure(bins[g]))
            source = bins[worst]
            destinations = [g for g in range(gpu_num) if g != worst]
            if not source or not destinations:
                break

            ranked = sorted(
                source,
                key=lambda i: -(loads[i] + gpu_pressure(source) * sizes[i])
            )[:12]
            candidates = []
            for mask in range(1, min(1 << len(ranked), 4096)):
                subset = [ranked[j] for j in range(len(ranked))
                          if mask & (1 << j)]
                removed_size = sum(sizes[i] for i in subset)
                if removed_size < GPU_MEM_SIZE - eps:
                    candidates.append((
                        sum(loads[i] + gpu_pressure(source) * sizes[i]
                            for i in subset),
                        -removed_size, subset
                    ))
            candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
            candidates = candidates[:32]

            current_value = placement_pressure(bins)
            chosen_state = None
            chosen_value = current_value
            base_sizes = {
                g: sum(sizes[i] for i in bins[g]) for g in destinations
            }
            base_loads = {
                g: sum(loads[i] for i in bins[g]) for g in destinations
            }

            for _, _, subset in candidates:
                q = len(subset)
                d = len(destinations)
                variables = q * d
                matrix = lil_matrix((q + d, variables), dtype=float)

                for j in range(q):
                    for z in range(d):
                        matrix[j, j * d + z] = 1.0
                for z, g in enumerate(destinations):
                    for j, i in enumerate(subset):
                        matrix[q + z, j * d + z] = sizes[i]

                costs = []
                for i in subset:
                    for g in destinations:
                        free = GPU_MEM_SIZE - base_sizes[g]
                        if free - sizes[i] <= eps:
                            costs.append(1e9)
                        else:
                            costs.append(
                                (base_loads[g] + loads[i]) /
                                (free - sizes[i])
                            )

                lower = np.r_[np.ones(q), np.full(d, -np.inf)]
                upper = np.r_[np.ones(q),
                              np.full(d, GPU_MEM_SIZE - eps)]
                result = milp(
                    np.asarray(costs, dtype=float),
                    integrality=np.ones(variables),
                    bounds=Bounds(0, 1),
                    constraints=LinearConstraint(
                        matrix.tocsr(), lower, upper
                    ),
                    options={"time_limit": 0.04},
                )
                if not result.success or result.x is None:
                    continue

                assignment = [[] for _ in destinations]
                feasible = True
                for j, i in enumerate(subset):
                    z = int(np.argmax(result.x[j * d:(j + 1) * d]))
                    if costs[j * d + z] >= 1e8:
                        feasible = False
                        break
                    assignment[z].append(i)
                if not feasible:
                    continue

                removed = set(subset)
                trial = [group[:] for group in bins]
                trial[worst] = [i for i in source if i not in removed]
                for z, g in enumerate(destinations):
                    trial[g].extend(assignment[z])
                    if GPU_MEM_SIZE - sum(sizes[i] for i in trial[g]) <= eps:
                        feasible = False
                        break
                if not feasible:
                    continue

                value = placement_pressure(trial)
                if value < chosen_value - 1e-12:
                    chosen_value = value
                    chosen_state = trial

            if chosen_state is None:
                break
            bins = chosen_state
    except Exception:
        pass

    return {g: [models[i] for i in bins[g]] for g in range(gpu_num)}


